// server/lib/storage.ts
import path2 from "path";
import fs2 from "fs";

// server/lib/cloudinary.ts
var cloudName = process.env.CLOUDINARY_CLOUD_NAME || "tdzyw4dr";
var apiKey = process.env.CLOUDINARY_API_KEY || "324635339443627";
var apiSecret = process.env.CLOUDINARY_API_SECRET || "sqzKzF5p5BfDxCyJUNQplamsZwA";
async function getSha1Hex(str) {
  if (typeof globalThis !== "undefined" && globalThis.crypto?.subtle) {
    const buffer = new TextEncoder().encode(str);
    const hash = await globalThis.crypto.subtle.digest("SHA-1", buffer);
    return Array.from(new Uint8Array(hash)).map((b) => b.toString(16).padStart(2, "0")).join("");
  }
  return "";
}
async function uploadToCloudinary(fileData, folder = "photos", filename) {
  try {
    const timestamp = Math.round(Date.now() / 1e3);
    const publicId = filename ? `pixelbooth/${folder}/${filename}` : `pixelbooth/${folder}/${Date.now()}`;
    const paramsToSign = `folder=pixelbooth/${folder}&public_id=${publicId}&timestamp=${timestamp}`;
    const signature = await getSha1Hex(paramsToSign + apiSecret);
    const formData = new FormData();
    if (typeof fileData === "string") {
      formData.append("file", fileData);
    } else {
      const blob = new Blob([fileData]);
      formData.append("file", blob, filename || "image.jpg");
    }
    formData.append("api_key", apiKey);
    formData.append("timestamp", String(timestamp));
    formData.append("folder", `pixelbooth/${folder}`);
    formData.append("public_id", publicId);
    formData.append("signature", signature);
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData
    });
    if (!res.ok) {
      const err = await res.text();
      console.warn("Cloudinary upload error, falling back to data URI:", err);
      if (typeof fileData === "string" && fileData.startsWith("data:")) {
        return fileData;
      }
      return typeof fileData === "string" ? `data:image/jpeg;base64,${fileData}` : `data:image/jpeg;base64,${fileData.toString("base64")}`;
    }
    const data = await res.json();
    return data.secure_url;
  } catch (error) {
    console.warn("Cloudinary network exception:", error);
    if (typeof fileData === "string" && fileData.startsWith("data:")) {
      return fileData;
    }
    return typeof fileData === "string" ? `data:image/jpeg;base64,${fileData}` : `data:image/jpeg;base64,${fileData.toString("base64")}`;
  }
}

// server/lib/storage.ts
async function saveMedia(fileData, folder, filename) {
  const isCloud = Boolean(
    process.env.VERCEL || process.env.VERCEL_ENV || process.env.CF_PAGES || process.env.CLOUDFLARE_WORKER || process.env.NODE_ENV === "production" || typeof globalThis.WebSocketPair !== "undefined"
  );
  if (isCloud) {
    return uploadToCloudinary(fileData, folder, filename);
  }
  try {
    let buffer;
    if (typeof fileData === "string") {
      if (fileData.includes(";base64,")) {
        const b64 = fileData.split(";base64,")[1];
        buffer = Buffer.from(b64, "base64");
      } else if (fileData.startsWith("data:")) {
        const b64 = fileData.split(",")[1];
        buffer = Buffer.from(b64, "base64");
      } else {
        try {
          buffer = Buffer.from(fileData, "base64");
        } catch {
          buffer = Buffer.from(fileData);
        }
      }
    } else {
      buffer = fileData;
    }
    const safeFilename = filename.endsWith(".jpg") || filename.endsWith(".png") || filename.endsWith(".webp") || filename.endsWith(".svg") ? filename : `${filename}.jpg`;
    const candidateDirs = [
      path2.resolve(process.cwd(), "../backend/storage/app/public", folder),
      path2.resolve(process.cwd(), "storage/app/public", folder)
    ];
    let targetDir = candidateDirs[0];
    for (const dir of candidateDirs) {
      if (fs2.existsSync(path2.dirname(dir))) {
        targetDir = dir;
        break;
      }
    }
    if (!fs2.existsSync(targetDir)) {
      fs2.mkdirSync(targetDir, { recursive: true });
    }
    const filePath = path2.join(targetDir, safeFilename);
    fs2.writeFileSync(filePath, buffer);
    return `/api/storage/${folder}/${safeFilename}`;
  } catch (err) {
    console.warn("Local disk write failed, fallback to Cloudinary:", err);
    return uploadToCloudinary(fileData, folder, filename);
  }
}

