// server/routes/customer.ts
var customerRouter = new Hono2();
customerRouter.get("/photo/:token", async (c) => {
  try {
    const token = c.req.param("token");
    const photo = await db.getPhotoByToken(token);
    if (!photo) {
      return c.json({ message: "Foto tidak ditemukan atau tautan kedaluwarsa" }, 404);
    }
    return c.json({ data: photo });
  } catch (err) {
    return c.json({ message: err?.message || "Gagal mengambil foto" }, 500);
  }
});
customerRouter.delete("/photo/:token", async (c) => {
  try {
    const token = c.req.param("token");
    await db.deletePhotoByToken(token);
    return c.json({ message: "Foto berhasil dihapus" });
  } catch (err) {
    return c.json({ message: err?.message || "Gagal menghapus foto" }, 500);
  }
});
customerRouter.post("/photos/bulk-delete", async (c) => {
  try {
    const { tokens } = await c.req.json().catch(() => ({ tokens: [] }));
    if (Array.isArray(tokens) && tokens.length > 0) {
      await db.bulkDeletePhotosByTokens(tokens);
    }
    return c.json({ message: `${tokens.length} foto berhasil dihapus` });
  } catch (err) {
    return c.json({ message: err?.message || "Gagal menghapus foto" }, 500);
  }
});
customerRouter.get("/folder/:token", async (c) => {
  try {
    const token = c.req.param("token");
    const folder = await db.getFolderByToken(token);
    if (!folder) {
      return c.json({ message: "Folder tidak ditemukan atau tautan kedaluwarsa" }, 404);
    }
    return c.json({ data: folder });
  } catch (err) {
    return c.json({ message: err?.message || "Gagal mengambil folder" }, 500);
  }
});

// server/app.ts
var app = new Hono2();
app.use("*", logger());
app.use("*", cors({
  origin: "*",
  allowMethods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
  allowHeaders: ["Content-Type", "Authorization", "Accept", "X-Requested-With"]
}));
var api = new Hono2();
api.get("/health", (c) => c.json({ status: "ok", server: "vercel-native-typescript", timestamp: (/* @__PURE__ */ new Date()).toISOString() }));
api.get("/storage/*", async (c) => {
  const filePath = c.req.path.replace(/^\/api\/storage\//, "").replace(/^\/storage\//, "");
  const candidates = [
    path4.resolve(process.cwd(), "../backend/storage/app/public", filePath),
    path4.resolve(process.cwd(), "../backend/public/storage", filePath),
    path4.resolve(process.cwd(), "storage/app/public", filePath)
  ];
  for (const candidate of candidates) {
    if (fs4.existsSync(candidate)) {
      const data = fs4.readFileSync(candidate);
      const ext = path4.extname(filePath).toLowerCase();
      const mime = {
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".gif": "image/gif",
        ".webp": "image/webp",
        ".svg": "image/svg+xml"
      };
      return new Response(data, { headers: { "Content-Type": mime[ext] || "application/octet-stream" } });
    }
  }
  return c.json({ message: "File tidak ditemukan" }, 404);
});
api.route("/templates", templatesRouter);
api.route("/sessions", sessionsRouter);
api.route("/folders", foldersRouter);
api.route("/photos", photosRouter);
api.route("/settings", settingsRouter);
api.route("/hardware", hardwareRouter);
api.route("/public", customerRouter);
app.route("/api", api);
app.route("/", api);
app.notFound((c) => c.json({ message: "Endpoint tidak ditemukan" }, 404));
app.onError((err, c) => {
  console.error("API Global Error:", err);
  return c.json({ message: err.message || "Internal Server Error" }, 500);
});

